<?php

namespace Database\Seeders;

use App\Models\NumberMeaning;
use Illuminate\Database\Seeder;

/**
 * Replaces ONLY the original auto-generated 1–999 descriptions.
 * Hand-written and subsequently edited records remain untouched.
 */
class RefineNumberMeaningsSeeder extends Seeder
{
    public function run(): void
    {
        $themes = [
            0 => ['пауза', 'пространство между решениями', 'позволить себе не знать', 'прятаться в ожидании идеального момента', 'Что изменится, если я перестану требовать от себя немедленного ответа?', 'Сделай паузу на минуту. Заметь, что происходит, когда не нужно ничего решать.'],
            1 => ['выбор', 'собственная инициатива', 'действовать, не дожидаясь разрешения', 'путать самостоятельность с одиночеством', 'Какое решение я откладываю, ожидая чужого одобрения?', 'Запиши один шаг, который можешь сделать без разрешения со стороны.'],
            2 => ['отношения', 'умение слышать', 'оставаться собой рядом с другим', 'уступать из страха потерять близость', 'Где я говорю «да», хотя внутри чувствую «нет»?', 'Вспомни недавний разговор и назови чувство, которое тогда не выразил.'],
            3 => ['голос', 'искреннее выражение', 'проявляться без стремления понравиться', 'заменять искренность красивыми словами', 'Что я давно хочу сказать, но подбираю слишком правильные слова?', 'Запиши три честных предложения без редактирования.'],
            4 => ['опора', 'устойчивость в повседневности', 'создавать порядок без жёсткости', 'принимать контроль за безопасность', 'Какая привычка помогает мне, а какая уже стала клеткой?', 'Выбери одну маленькую опору на сегодня: сон, движение или завершённое дело.'],
            5 => ['перемены', 'готовность к новому', 'двигаться, не теряя связи с собой', 'убегать от трудного под видом свободы', 'От чего я хочу уйти — и к чему на самом деле хочу прийти?', 'Назови одну перемену и её истинную причину. Не торопись действовать.'],
            6 => ['забота', 'бережное присутствие', 'помогать, сохраняя собственные границы', 'забывать о себе, становясь нужным всем', 'Кому я помогаю ценой собственного истощения?', 'Сделай для себя то, что обычно делаешь только для других.'],
            7 => ['тишина', 'внимательное исследование', 'слышать себя за шумом мыслей', 'бесконечно искать смысл вместо того, чтобы жить', 'Какой ответ я пытаюсь выдумать, вместо того чтобы заметить?', 'Две минуты наблюдай за мыслями, не споря с ними.'],
            8 => ['ответственность', 'зрелое обращение с ресурсами', 'влиять без давления', 'измерять собственную ценность результатами', 'Кто я, когда сегодня ничего не достигаю?', 'Отдели список дел от списка того, что действительно важно.'],
            9 => ['завершение', 'умение отпускать', 'признавать пройденный путь', 'держаться за прошлое из чувства долга', 'Что закончилось в моей жизни, хотя я продолжаю это удерживать?', 'Запиши одну вещь, за которую благодарен прошлому, и одну, которую отпускаешь.'],
        ];

        $openings = [
            'Иногда мы замечаем число в тот момент, когда внутри уже назрел вопрос. ',
            'Представь это число не как указание судьбы, а как зеркало для внимания. ',
            'Не нужно верить, что совпадение что-то предсказывает. Можно использовать его как повод остановиться. ',
            'У чисел нет обязанности объяснять нашу жизнь. Но символ способен подсветить привычную реакцию. ',
            'Смысл здесь рождается не в цифрах, а в том, что ты замечаешь, размышляя о них. ',
            'Попробуй на мгновение оставить поиск тайного послания и посмотреть на собственный опыт. ',
        ];
        $bridges = [
            'Первый образ — %s; затем появляется %s. Между ними может скрываться знакомое напряжение: одно важно, но другое тоже требует места.',
            'Здесь встречаются %s и %s. Не нужно выбирать что-то одно: полезнее заметить, как они сосуществуют в твоих решениях.',
            'От темы «%s» взгляд переходит к теме «%s». Вспомни ситуацию, когда этот переход происходил в твоей жизни.',
            'Один край этого символа — %s, другой — %s. Что меняется, если увидеть обе стороны одновременно?',
            'Число предлагает рассмотреть связь двух человеческих тем: %s и %s. Возможно, именно их баланс сейчас заслуживает внимания.',
        ];
        $centers = [
            'В середине стоит %s — образ, который можно прочитать как невысказанный вопрос между началом и итогом.',
            'Центральная цифра добавляет тему «%s». Иногда именно промежуточный шаг мы не замечаем.',
            'Между крайними цифрами находится %s. Попробуй увидеть в этом не знак, а напоминание о процессе.',
        ];
        $endings = [
            'Не спеши превращать это размышление в вывод о себе. Достаточно честно заметить, что откликается.',
            'Если ничего не откликается, это тоже нормально: символ не обязан подходить к твоей ситуации.',
            'Самое важное здесь не найти правильное толкование, а услышать собственный ответ.',
            'Пусть это останется вопросом, а не новым правилом, которому нужно соответствовать.',
        ];

        $updated = 0;
        for ($n = 1; $n <= 999; $n++) {
            $record = NumberMeaning::query()->where('number', (string) $n)->first();
            if (!$record || !str_starts_with((string) $record->symbolism, 'Число ' . $n . ' можно использовать как повод для самонаблюдения.')) {
                continue;
            }

            $digits = array_map('intval', str_split((string) $n));
            $first = $themes[$digits[0]];
            $last = $themes[$digits[count($digits) - 1]];
            $sum = array_sum($digits);
            while ($sum > 9) {
                $sum = array_sum(array_map('intval', str_split((string) $sum)));
            }
            $core = $themes[$sum];
            $index = $n % count($openings);
            $bridge = sprintf($bridges[$n % count($bridges)], $first[1], $last[1]);
            $special = '';
            if (count($digits) === 3) {
                $middle = $themes[$digits[1]];
                $special = ' ' . sprintf($centers[$n % count($centers)], $middle[0]);
            }
            if (count(array_unique($digits)) === 1 && count($digits) > 1) {
                $special .= ' Повтор одной цифры можно использовать как приглашение вернуться к одной и той же теме с разных сторон.';
            } elseif (count($digits) === 3 && $digits[0] === $digits[2]) {
                $special .= ' Первая и последняя цифры совпадают: красивый образ возвращения к исходному вопросу после прожитого опыта.';
            } elseif (in_array(0, $digits, true)) {
                $special .= ' Ноль здесь можно воспринимать как паузу: не всякое пространство нужно немедленно заполнить действием.';
            }

            $record->update([
                'title' => mb_convert_case($core[0], MB_CASE_TITLE, 'UTF-8') . ': ' . $first[0] . ' и ' . $last[0],
                'symbolism' => $openings[$index] . $bridge . $special . ' Если сложить цифры числа ' . $n . ' и свести сумму к одной, получится ' . $sum . '. В нашей условной системе это тема «' . $core[0] . '». ' . $endings[$n % count($endings)],
                'light_side' => 'Представь, что ' . $core[1] . ' — не требование стать лучше, а уже доступная тебе возможность. ' . 'В ситуации, где сталкиваются ' . $first[0] . ' и ' . $last[0] . ', попробуй проявить это качество мягко, без борьбы с собой.',
                'shadow_side' => 'Иногда мы незаметно начинаем ' . $core[3] . '. Это лишь возможная тема для наблюдения, не характеристика твоей личности. Заметь, в каких обстоятельствах такая реакция появляется и от чего она пытается тебя защитить.',
                'reflection_question' => $core[4] . ' А как этот вопрос связан с темами «' . $first[0] . '» и «' . $last[0] . '» именно в твоей жизни?',
                'practice' => $core[5] . ' Затем запиши одну конкретную ситуацию сегодняшнего дня, которая пришла на ум. Не оценивай её как хорошую или плохую.',
            ]);
            $updated++;
        }

        $this->command?->info('Обновлены автоматически созданные толкования: ' . $updated . '. Ручные записи сохранены.');
    }
}
